const item = { ...$input.first().json };
const fail = (code) => { throw new Error(code); };

if (typeof item.ai_name !== 'string') fail('INVALID_AI_NAME_TYPE');
const rawName = item.ai_name;
const safeName = rawName.trim();
if (!safeName || safeName !== rawName) fail('INVALID_AI_NAME_WHITESPACE');
if (safeName.length > 120) fail('INVALID_AI_NAME_TOO_LONG');
if (/[\x00-\x1f\x7f]/.test(safeName)) fail('INVALID_AI_NAME_CONTROL');
if (safeName.includes('..')) fail('INVALID_AI_NAME_TRAVERSAL');
if (/[\\/:<>"|?*]/.test(safeName)) fail('INVALID_AI_NAME_CHARACTER');
if (/^[A-Za-z]:/.test(safeName) || /^[\\/]/.test(safeName)) fail('INVALID_AI_NAME_ABSOLUTE');
if (/[. ]$/.test(safeName)) fail('INVALID_AI_NAME_TRAILING');
const reserved = new Set(['CON','PRN','AUX','NUL','COM1','COM2','COM3','COM4','COM5','COM6','COM7','COM8','COM9','LPT1','LPT2','LPT3','LPT4','LPT5','LPT6','LPT7','LPT8','LPT9']);
if (reserved.has(safeName.split('.', 1)[0].toUpperCase())) fail('INVALID_AI_NAME_RESERVED');

if (item.source_url !== undefined && item.source_url !== null && typeof item.source_url !== 'string') {
  fail('INVALID_SOURCE_URL_TYPE');
}
const sourceUrl = String(item.source_url || '').trim();
if (sourceUrl) {
  const match = sourceUrl.match(/^(https?):\/\/([^\/?#]+)(?:[\/?#]|$)/i);
  if (!match) fail('UNSAFE_SOURCE_URL_SCHEME_OR_AUTH');
  const authority = match[2];
  if (authority.includes('@')) fail('UNSAFE_SOURCE_URL_SCHEME_OR_AUTH');
  let host;
  if (authority.startsWith('[')) {
    const end = authority.indexOf(']');
    if (end < 0 || (authority.slice(end + 1) && !/^:\d{1,5}$/.test(authority.slice(end + 1)))) fail('INVALID_SOURCE_URL');
    host = authority.slice(1, end);
  } else {
    const pieces = authority.split(':');
    if (pieces.length > 2 || (pieces[1] && !/^\d{1,5}$/.test(pieces[1]))) fail('INVALID_SOURCE_URL');
    host = pieces[0];
  }
  host = host.toLowerCase().replace(/\.$/, '');
  if (!host) fail('INVALID_SOURCE_URL');
  const blockedName = host === 'localhost' || host.endsWith('.localhost') || host.endsWith('.local');
  const blockedV4 = /^(?:0\.|10\.|127\.|169\.254\.|192\.168\.)/.test(host) ||
    /^172\.(?:1[6-9]|2\d|3[01])\./.test(host) || host === '255.255.255.255';
  const blockedV6 = host === '::' || host === '::1' || /^(?:fc|fd)/.test(host) ||
    /^fe[89ab]/.test(host) || host.startsWith('::ffff:');
  if (blockedName || blockedV4 || blockedV6) fail('UNSAFE_SOURCE_URL_PRIVATE_TARGET');
  item.source_url = sourceUrl;
} else {
  item.source_url = '';
}

item.ai_name = safeName;
item.safe_ai_name = safeName;
item.filename_policy = 'FAIL_CLOSED_V0.1';
item.source_url_policy = 'PUBLIC_HTTP_HTTPS_LITERAL_GUARD_V0.1';
return [{ json: item }];
